// Ambil ig_token yang sedang dipakai dari node Kredensial workflow publish.
//
// Tokennya sengaja dibaca dari sana, bukan disalin ke workflow ini: kalau ada dua
// salinan, yang satu pasti basi dan refresh-nya memperpanjang token yang sudah tidak
// dipakai siapa-siapa. Satu tempat penyimpanan, dan tetap yang itu juga yang bisa
// diedit tangan.
const wf = $input.first().json;
const nodes = wf.nodes || [];

if (!nodes.length) {
  throw new Error(
    `Balasan API tidak memuat nodes[]. Cek workflow_id dan n8n_api_key. ` +
      `Dapat: ${JSON.stringify(wf).slice(0, 300)}`
  );
}

const kred = nodes.find((n) => n.name === 'Kredensial');
if (!kred) {
  throw new Error(
    `Workflow "${wf.name || '?'}" tidak punya node bernama "Kredensial" — ` +
      'kemungkinan workflow_id menunjuk workflow lain.'
  );
}

const daftar = (kred.parameters && kred.parameters.assignments && kred.parameters.assignments.assignments) || [];
const field = daftar.find((a) => a.name === 'ig_token');
if (!field || !field.value) {
  throw new Error('Node "Kredensial" tidak punya field ig_token yang terisi.');
}
// Placeholder hasil build yang belum diisi. Meneruskannya bikin refresh dibalas 400
// dengan pesan Meta yang tidak menyebut sebab aslinya.
if (/^ISI_[A-Z0-9_]+$/.test(field.value)) {
  throw new Error(`ig_token masih placeholder (${field.value}) — isi dulu di workflow publish.`);
}

return [{ json: { token_lama: field.value, nama_workflow: wf.name || '' } }];

// Susun badan PUT /api/v1/workflows/{id}: workflow yang sama persis, satu nilai diganti.
//
// Dibangun dari salinan utuh hasil GET, bukan dari potongan: PUT itu mengganti seluruh
// workflow, jadi field apa pun yang tidak ikut dikirim akan HILANG. Bukan sekadar
// "tidak diperbarui" — hilang.
const wf = $('Ambil workflow').first().json;
const refresh = $input.first().json;
const baru = refresh.access_token;

if (!baru) {
  throw new Error(
    `refresh_access_token tidak mengembalikan access_token: ${JSON.stringify(refresh).slice(0, 300)}`
  );
}

const nodes = JSON.parse(JSON.stringify(wf.nodes));
const kred = nodes.find((n) => n.name === 'Kredensial');
const field = kred.parameters.assignments.assignments.find((a) => a.name === 'ig_token');
const lama = field.value;
field.value = baru;

// Token baru identik dengan yang lama berarti Meta memantulkan balik permintaannya.
// Menyimpannya tidak merusak apa pun, tapi diam-diam tidak memperpanjang apa pun juga
// — dan bulan depan tokennya mati tanpa ada yang pernah memberi tahu.
if (lama === baru) {
  throw new Error('Token baru identik dengan yang lama — refresh tidak menghasilkan masa berlaku baru.');
}

// PUT hanya menerima empat properti ini. Menyertakan id/active/tags/pinData/versionId
// atau meta dibalas 400 "must NOT have additional properties", dan pesannya tidak
// menyebut properti mana yang jadi masalah.
return [{
  json: {
    body: {
      name: wf.name,
      nodes,
      connections: wf.connections,
      settings: wf.settings || { executionOrder: 'v1' },
    },
  },
}];

// Periksa balasan PUT, bukan sekadar percaya HTTP 200.
//
// Node HTTP di atas memakai onError:continueRegularOutput supaya kegagalan tetap
// sampai ke e-mail — tanpa ini pekerjaan terjadwal yang gagal cuma jadi eksekusi merah
// di dasbor yang tidak pernah dibuka siapa pun, dan tokennya mati dua bulan kemudian.
const refresh = $('Refresh token').first().json;
const simpan = $input.first().json;
const lama = $('Ambil token lama').first().json.token_lama;
const baru = refresh.access_token || '';

const masalah = [];

if (refresh.error || !baru) {
  masalah.push(`refresh gagal: ${JSON.stringify(refresh).slice(0, 300)}`);
}

const kred = (simpan.nodes || []).find((n) => n.name === 'Kredensial');
const tersimpan =
  kred && (kred.parameters.assignments.assignments || []).find((a) => a.name === 'ig_token');

if (!tersimpan) {
  masalah.push(`balasan PUT tidak memuat node Kredensial: ${JSON.stringify(simpan).slice(0, 300)}`);
} else if (tersimpan.value !== baru) {
  masalah.push('token di workflow publish tidak berubah — yang tersimpan masih yang lama.');
}

// PUT mengganti seluruh workflow. Kalau prosesnya sampai menonaktifkannya, webhook
// publish ikut mati dan push berikutnya gagal tanpa sebab yang kelihatan.
if (simpan.active === false) {
  masalah.push('Workflow publish jadi NONAKTIF setelah disimpan — aktifkan lagi di n8n sekarang juga.');
}

const detik = Number(refresh.expires_in || 0);

return [{
  json: {
    ok: masalah.length === 0,
    hari: Math.round(detik / 86400),
    // Tanggal, bukan cuma jumlah hari: yang berguna saat membaca e-mail sebulan lagi.
    kedaluwarsa: new Date(Date.now() + detik * 1000).toISOString().slice(0, 10),
    // Hanya ekornya. E-mail itu penyimpanan jangka panjang yang tidak dienkripsi —
    // enam karakter sudah cukup untuk memastikan tokennya benar-benar berganti.
    ekor_lama: String(lama).slice(-6),
    ekor_baru: baru.slice(-6),
    masalah,
  },
}];
